CREATE TABLE IF NOT EXISTS continental_jurisdiction_matrix (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), jurisdiction_id uuid NOT NULL REFERENCES jurisdictions(id) ON DELETE CASCADE, rights_domain text NOT NULL, rights_position text NOT NULL DEFAULT 'Unknown', legal_basis text, recognition_status text NOT NULL DEFAULT 'Unknown', authority_required boolean NOT NULL DEFAULT false, community_protection_gate boolean NOT NULL DEFAULT false, foreign_ownership_gate boolean NOT NULL DEFAULT false, evidence_reference text, effective_from date, effective_to date, notes text, status text NOT NULL DEFAULT 'Active', UNIQUE(jurisdiction_id,rights_domain));
CREATE TABLE IF NOT EXISTS continental_jurisdiction_requirements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), jurisdiction_id uuid NOT NULL REFERENCES jurisdictions(id) ON DELETE CASCADE, domain_code text NOT NULL, requirement_code text NOT NULL, requirement_name text NOT NULL, trigger_condition text, mandatory boolean NOT NULL DEFAULT true, evidence_required text, approving_authority text, renewal_or_expiry text, legal_basis text, source_reference text, status text NOT NULL DEFAULT 'Active', UNIQUE(jurisdiction_id,requirement_code));
CREATE TABLE IF NOT EXISTS asset_jurisdiction_matrix_assessments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), asset_id uuid NOT NULL REFERENCES continental_assets(id) ON DELETE CASCADE, jurisdiction_id uuid NOT NULL REFERENCES jurisdictions(id) ON DELETE CASCADE, assessment_version text NOT NULL DEFAULT '1.0', rights_position text NOT NULL DEFAULT 'Unassessed', compliance_position text NOT NULL DEFAULT 'Unassessed', community_rights_position text NOT NULL DEFAULT 'Unassessed', foreign_ownership_position text NOT NULL DEFAULT 'Unassessed', blocking_issue_count integer NOT NULL DEFAULT 0, required_action_count integer NOT NULL DEFAULT 0, confidence_score numeric(6,2), rationale text, assessed_at timestamptz NOT NULL DEFAULT now(), assessor_reference text, status text NOT NULL DEFAULT 'Draft', UNIQUE(asset_id,jurisdiction_id,assessment_version));
CREATE TABLE IF NOT EXISTS asset_jurisdiction_matrix_requirements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), assessment_id uuid NOT NULL REFERENCES asset_jurisdiction_matrix_assessments(id) ON DELETE CASCADE, requirement_id uuid NOT NULL REFERENCES continental_jurisdiction_requirements(id) ON DELETE CASCADE, fulfilment_status text NOT NULL DEFAULT 'Pending', blocking boolean NOT NULL DEFAULT false, evidence_reference text, reviewer_reference text, notes text, decided_at timestamptz, status text NOT NULL DEFAULT 'Open');
CREATE INDEX IF NOT EXISTS idx_cjm_jurisdiction ON continental_jurisdiction_matrix(jurisdiction_id,rights_domain);
CREATE INDEX IF NOT EXISTS idx_cjr_jurisdiction ON continental_jurisdiction_requirements(jurisdiction_id,domain_code);
CREATE INDEX IF NOT EXISTS idx_ajma_asset ON asset_jurisdiction_matrix_assessments(asset_id,assessed_at DESC);
CREATE INDEX IF NOT EXISTS idx_ajmr_assessment ON asset_jurisdiction_matrix_requirements(assessment_id,fulfilment_status);